#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <queue>
#include <set>
#include <map>
#include <stack>
using namespace std;

typedef long long LL;
const int MAXN=250100;

int read_input() {
    int val=0; bool sign=true; char c=getchar();
    while ((c<'0'||c>'9') && c!='-') c=getchar();
    if (c=='-') { sign=false; c=getchar(); }
    while (c>='0' && c<='9') { val=val*10+c-'0'; c=getchar(); }
    return sign ? val : -val;
}

int MOD, mVal;
int sizeArr[MAXN], invArr[MAXN];
struct Data { int a[19]; } dataArr[MAXN];

inline int powerMod(int base, int exp) {
    int res=1;
    while (exp) {
        if (exp & 1) res=1LL*res*base%MOD;
        base=1LL*base*base%MOD; exp>>=1;
    }
    return res;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("CF838C.in","r",stdin);
    freopen("CF838C.out","w",stdout);
#endif
    int i, s, n=read_input(), k=read_input(), a, b, y, t[20]={}, p[20]={};
    Data *F, *G;
    MOD=read_input();

    if (n%2==1) {
        printf("%d\n", powerMod(k, n));
        return 0;
    }

    for (i=0; i<18; i++) mVal+= (n>>i)&1;

    for (i=0, s=1; i<=n; i++) {
        invArr[i]=i<2 ? 1 : -1LL*(MOD/i)*invArr[MOD%i]%MOD;
        sizeArr[i]=sizeArr[i>>1]+(i&1);
        s=1LL*s*invArr[i]%MOD;
        if ((i&n)==i)
            dataArr[i].a[sizeArr[i]]=s;
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&dataArr[s^(1<<i)], G=&dataArr[s]; a<=mVal; a++) (G->a[a]+=F->a[a])%=MOD;

    for (i=0; i<=n; i++) if ((i&n)==i) {
        F=&dataArr[i];
        for (a=0; a<=mVal; a++) y[a]=F->a[a], F->a[a]=!a;
        for (b=k; b; b>>=1) {
            if (b&1) {
                for (a=0; a<=mVal; a++) p[a]=F->a[a], F->a[a]=0;
                for (a=0; a<=mVal; a++)
                    if (y[a])
                        for (b=0; a+b<=mVal; b++)
                            F->a[a+b]=(F->a[a+b]+1LL*y[a]*p[b])%MOD;
            }
            if (b>>=1) {
                for (a=0; a<=mVal; a++) p[a]=y[a], y[a]=0;
                for (a=0; a<=mVal; a++)
                    if (p[a])
                        for (b=0; a+b<=mVal; b++)
                            y[a+b]=(y[a+b]+1LL*p[a]*p[b])%MOD;
            }
        }
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&dataArr[s^(1<<i)], G=&dataArr[s]; a<=mVal; a++) (G->a[a]-=F->a[a])%=MOD;

    y=dataArr[n].a[mVal];
    for (i=n; i; i--) y=1LL*y*i%MOD;
    printf("%d\n", ((powerMod(k, n)-y)%MOD+MOD)%MOD);
    return 0;
}
